import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { createProductVariantsWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await createProductVariantsWorkflow(req.scope)
    .run({
      input: {
        product_variants: [{
          product_id: "prod_123",
          sku: "SHIRT-123",
          title: "Small Shirt",
          prices: [{
            amount: 10,
            currency_code: "USD",
          }, ],
          options: {
            Size: "Small",
          },
        }, ],
        additional_data: {
          erp_id: "123"
        }
      }
    })

  res.send(result)
}

